package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;import static com.bridge.quartercore.NativeSheetsModel.*;
class HistoricalMigrationAuthorityTest {
 static final GoogleSheetsBinding B=JournalSessionAuthorityTest.BINDING;static final Clock CLOCK=Clock.systemUTC();
 static class Fixture {
  Book book;InitialCutoverAuthority bootstrap;HistoricalCasualMigrationPlan.Approval approval;
  Fixture()throws Exception{book=InitialCutoverAuthorityTest.legacy();var e=com.bridge.persistence.HistoricalAdmissionTest.original(book.sheet("accounts").rows.get(1).get(0));book.sheet("commits").rows=new ArrayList<>(List.of(ManualQuarterMaintenance.HEADERS.get("commits"),List.of(e.commitId(),e.payloadHash(),"1",e.matchId(),"1")));book.sheet("envelopes").rows=new ArrayList<>(List.of(ManualQuarterMaintenance.HEADERS.get("envelopes"),List.of(e.commitId(),e.payloadHash(),"0","1",e.canonicalJson())));book.sheet("retention_ledger").rows.add(List.of("2026-Q4","2026-09-30T16:00:00Z","COMPLETE",CLOCK.instant().toString(),"1"));bootstrap=new InitialCutoverAuthority(B,InitialCutoverAuthorityTest.plan(book,(t,h,z)->{}),CLOCK);bootstrap.execute(()->book,w->{var ticket=bootstrap.beforeDispatch(B.path()+":batchUpdate",w);book=simulate(book,w);ticket.acknowledged();},()->book);approval=new HistoricalCasualMigrationPlan.Approval(B.manualBinding(),NativeCommitJournal.digest(B.manualBinding(),book),e.commitId(),e.payloadHash(),UUID.randomUUID().toString(),new LifetimeStatistics.Counts(1,1,0,1,0,-1,1,0,0));}
  HistoricalMigrationAuthority authority(CutoverAssessment.FreezeVerifier verifier){return HistoricalMigrationAuthority.approveFromBootstrap(B,book,bootstrap.verifiedResult(),approval,true,CLOCK,new CutoverAssessment.FreezeEvidence("fresh-B1","independent",CLOCK.instant().plusSeconds(120)),verifier);}
  Book execute(HistoricalMigrationAuthority a){return a.execute(()->book,w->{var d=a.beforeDispatch(B.path()+":batchUpdate",w);book=simulate(book,w);d.acknowledged();},()->book);}
 }
 @Test void exactB1ProofAndReadbackProduceImmutableB2NoReplay()throws Exception{var f=new Fixture();var a=f.authority((t,h,e)->assertEquals(f.bootstrap.verifiedResult().afterToken(),h));var after=f.execute(a);assertEquals(HistoricalMigrationAuthority.State.VERIFIED,a.state());var proof=a.verifiedResult();assertSame(f.bootstrap.verifiedResult(),proof.bootstrap());assertEquals(JournalSessionAuthority.fullToken(after),proof.afterToken());a.closeUnknown();assertSame(proof,a.verifiedResult());assertThrows(RuntimeException.class,()->f.execute(a));}
 @Test void unknownAndWrongProofCannotResumeOrMintCompletion()throws Exception{var f=new Fixture();var other=new Fixture();assertThrows(RuntimeException.class,()->HistoricalMigrationAuthority.approveFromBootstrap(B,f.book,other.bootstrap.verifiedResult(),f.approval,true,CLOCK,new CutoverAssessment.FreezeEvidence("new","new",CLOCK.instant().plusSeconds(60)),(t,h,e)->{}));var a=f.authority((t,h,e)->{});assertThrows(RuntimeException.class,()->a.execute(()->f.book,w->{var d=a.beforeDispatch(B.path()+":batchUpdate",w);f.book=simulate(f.book,w);d.unknown();throw new Unknown();},()->f.book));assertThrows(RuntimeException.class,a::verifiedResult);assertThrows(RuntimeException.class,()->f.execute(a));}
 @Test void revocationDuringFreezeIoCannotDispatch()throws Exception{var f=new Fixture();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var calls=new AtomicInteger();var posts=new AtomicInteger();var a=f.authority((t,h,e)->{if(calls.incrementAndGet()==3){entered.countDown();try{release.await(2,TimeUnit.SECONDS);}catch(InterruptedException ex){throw new RuntimeException(ex);}}});var pool=Executors.newSingleThreadExecutor();try{var task=pool.submit(()->assertThrows(RuntimeException.class,()->a.execute(()->f.book,w->{a.beforeDispatch(B.path()+":batchUpdate",w);posts.incrementAndGet();},()->f.book)));assertTrue(entered.await(2,TimeUnit.SECONDS));a.closeUnknown();release.countDown();task.get(2,TimeUnit.SECONDS);assertEquals(0,posts.get());}finally{release.countDown();pool.shutdownNow();}}
 @Test void wrongTargetAndDefaultOffRejectBeforeCredentialRead()throws Exception{var f=new Fixture();var a=f.authority((t,h,e)->{});var count=new AtomicInteger();QuarterGoogleFactory.CredentialSource key=()->{count.incrementAndGet();throw new AssertionError();};assertThrows(RuntimeException.class,()->HistoricalMigrationGoogleFactory.open(new JournalGoogleFactory.Configuration(B.spreadsheetId(),B.datasetId(),B.purpose(),B.serviceAccountIssuer(),key),a));assertThrows(RuntimeException.class,()->HistoricalMigrationGoogleFactory.open(new JournalGoogleFactory.Configuration(true,"wrong-sheet",B.datasetId(),B.purpose(),B.serviceAccountIssuer(),key),a));assertEquals(0,count.get());}
 @Test void freezeCallbackCrossingDeadlineRejectsBeforePost()throws Exception{
  var f=new Fixture();var time=new CrossQuarterNativeSettlementTest.Time();time.now=CLOCK.instant();var calls=new AtomicInteger();var posts=new AtomicInteger();var a=HistoricalMigrationAuthority.approveFromBootstrap(B,f.book,f.bootstrap.verifiedResult(),f.approval,true,time,new CutoverAssessment.FreezeEvidence("fresh","source",time.instant().plusSeconds(2)),(t,h,e)->{if(calls.incrementAndGet()==3)time.now=time.now.plusSeconds(3);});
  assertThrows(RuntimeException.class,()->a.execute(()->f.book,w->{a.beforeDispatch(B.path()+":batchUpdate",w);posts.incrementAndGet();},()->f.book));assertEquals(0,posts.get());assertEquals(HistoricalMigrationAuthority.State.UNKNOWN,a.state());
 }
}
